#!/usr/bin/env bash\n\n# Nightly SSH Key Rotator\n# Generates a new RSA key pair, distributes the public key to a list of hosts,\n# and optionally removes an old key fingerprint from each host's authorized_keys.\n\nset -euo pipefail\n\nusage() {\n  cat <<'EOF'\nUsage: $0 -u USER -f HOSTS_FILE [-k OLD_FINGERPRINT]\n\n  -u USER            Remote username for SSH connections\n  -f HOSTS_FILE      File containing hostnames (one per line)\n  -k OLD_FINGERPRINT Optional exact line from authorized_keys to remove\nEOF\n  exit 1\n}\n\n# Parse arguments\nwhile getopts ":u:f:k:h" opt; do\n  case $opt in\n    u) USER="$OPTARG";;\n    f) HOSTS_FILE="$OPTARG";;\n    k) OLD_FINGERPRINT="$OPTARG";;\n    h) usage;;\n    \?) echo "Invalid option: -$OPTARG" >&2; usage;;\n    :) echo "Option -$OPTARG requires an argument." >&2; usage;;\n  esac\ndone\n\nif [[ -z "${USER:-}" || -z "${HOSTS_FILE:-}" ]]; then\n  echo "User and hosts file are required." >&2\n  usage\nfi\n\nif [[ ! -f "$HOSTS_FILE" ]]; then\n  echo "Hosts file not found: $HOSTS_FILE" >&2\n  exit 1\nfi\n\nTMP_DIR=$(mktemp -d -t ssh_key_rotator_XXXX)\ncleanup() {\n  rm -rf "$TMP_DIR"\n}\ntrap cleanup EXIT\n\ngenerate_key() {\n  ssh-keygen -t rsa -b 4096 -N "" -f "$TMP_DIR/id_rsa" >/dev/null\n}\n\n# Distribute the public key to each host\n# The command appends the key to ~/.ssh/authorized_keys, creating the file/dir if needed\n\nadd_key_to_host() {\n  local host="$1"\n  ssh "$USER@$host" "mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys" < "$TMP_DIR/id_rsa.pub"\n}\n\nremove_key_from_host() {\n  local host="$1"\n  # Use sed to delete the exact line matching the old fingerprint\n  ssh "$USER@$host" "sed -i \\`/$(printf "%s" "$OLD_FINGERPRINT" | sed 's/[\/&]/\\&/g')/d\\` ~/.ssh/authorized_keys"\n}\n\n# Main execution\ngenerate_key\n\nwhile IFS= read -r host || [[ -n "$host" ]]; do\n  # Skip empty lines or comments\n  [[ -z "$host" || "$host" =~ ^# ]] && continue\n  add_key_to_host "$host"\n  if [[ -n "${OLD_FINGERPRINT:-}" ]]; then\n    remove_key_from_host "$host"\n  fi\n done < "$HOSTS_FILE"\n\n# Output the private key to stdout for the caller to capture\ncat "$TMP_DIR/id_rsa"\n
